// Generated by GraphQL Monster Builder. Runtime shared by the server and migration CLI.
const fs = require('fs')
const path = require('path')
const crypto = require('crypto')
const knex = require('knex')

const root = path.resolve(__dirname, '../..')
const directory = path.join(root, 'database/migrations')
const snapshot = () => JSON.parse(fs.readFileSync(path.join(root, 'database/schema.snapshot.json'), 'utf8'))
let connection
const checksumTable = '_gmb_migration_checksums'
const checksum = file => crypto.createHash('sha256').update(fs.readFileSync(path.join(directory, file))).digest('hex')
const files = () => fs.readdirSync(directory).filter(f => /^\d{6}_[a-f0-9]{12}\.cjs$/.test(f)).sort()

function getConnection(options = {}) {
    if (!connection) {
        const provider = snapshot().schema.provider
        connection = knex({
            client: provider === 'postgresql' ? 'pg' : 'mysql2',
            connection: process.env.DATABASE_URL || {
                host: options.host || process.env.DB_HOST || '127.0.0.1',
                port: Number(process.env.DB_PORT || (provider === 'postgresql' ? 5432 : 3306)),
                database: options.db || process.env.DB_NAME || 'db_graphql_monster',
                user: process.env.DB_USER,
                password: process.env.DB_PASSWORD,
            },
            pool: { min: 0, max: 10 },
            migrations: { tableName: '_gmb_migrations' },
        })
    }
    return connection
}

async function verifyHistory(db) {
    if (!(await db.schema.hasTable(checksumTable))) return
    for (const row of await db(checksumTable).select('*')) {
        if (!files().includes(row.name) || checksum(row.name) !== row.checksum) {
            throw new Error(`Applied migration was changed or removed: ${row.name}. Restore it and create a new migration.`)
        }
    }
}

const migrationSource = {
    getMigrations: async () => files(),
    getMigrationName: file => file,
    getMigration: async file => {
        const migration = require(path.join(directory, file))
        return {
            ...migration,
            up: async db => {
                await migration.up(db)
                await db(checksumTable).insert({ name: file, checksum: checksum(file) })
            },
        }
    },
}

async function migrate(command = 'up') {
    const db = getConnection()
    await verifyHistory(db)
    if (command === 'status') {
        const [applied, pending] = await db.migrate.list({ migrationSource })
        return { applied: applied.map(m => m.name), pending: pending.map(m => typeof m === 'string' ? m : m.file || m.name) }
    }
    if (command !== 'up') throw new Error(`Unknown migration command: ${command}`)
    if (!(await db.schema.hasTable(checksumTable))) await db.schema.createTable(checksumTable, t => {
        t.string('name', 255).primary()
        t.string('checksum', 64).notNullable()
    })
    const [, applied] = await db.migrate.latest({ migrationSource })
    return { applied }
}

async function assertCurrent() {
    const db = getConnection()
    await verifyHistory(db)
    if (!(await db.schema.hasTable(checksumTable))) throw new Error('Database has not been migrated. Run npm run db:migrate.')
    const applied = await db(checksumTable).pluck('name')
    const pending = files().filter(file => !applied.includes(file))
    if (pending.length) throw new Error(`Database migrations are pending: ${pending.join(', ')}. Run npm run db:migrate.`)
    const last = files().slice(-1)[0]
    if (!last || require(path.join(directory, last)).schemaHash !== snapshot().hash) throw new Error('Database migration history does not match the generated schema')
}

async function close() {
    if (connection) {
        const db = connection
        connection = undefined
        await db.destroy()
    }
}

module.exports = { getConnection, migrate, assertCurrent, close, snapshot }
